// ##################

import { createFileRoute } from "@tanstack/react-router";
import { requirePermission } from "@/utils/require-permission";
import { z } from "zod";
import { useState, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { trpc } from "@/utils/trpc";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  IconClipboardCheck,
  IconLoader2,
  IconCheck,
  IconX,
  IconAlertCircle,
} from "@tabler/icons-react";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

export const Route = createFileRoute(
  "/(core)/back-office/pelatihan/$pelatihanId/penilaian",
)({
  params: z.object({
    pelatihanId: z.string(),
  }),
  beforeLoad: async ({ context }) =>
    await requirePermission(context, {
      permission: "pelatihan-enrollments.read",
    }),
  component: PenilaianTab,
});

const statusAttemptConfig: Record<string, { label: string; cls: string }> = {
  submitted: {
    label: "Perlu Penilaian",
    cls: "bg-amber-100 text-amber-700 border-amber-200",
  },
  graded: {
    label: "Selesai Dinilai",
    cls: "bg-emerald-100 text-emerald-700 border-emerald-200",
  },
  in_progress: {
    label: "Sedang Dikerjakan",
    cls: "bg-blue-100 text-blue-700 border-blue-200",
  },
};

function PenilaianTab() {
  const { pelatihanId } = Route.useParams();
  const [statusFilter, setStatusFilter] = useState<string>("submitted");
  const [activeAttemptId, setActiveAttemptId] = useState<string | null>(null);
  const [essayGrades, setEssayGrades] = useState<
    Record<string, { pointsEarned: number; feedback: string }>
  >({});

  // Query attempts for grading
  const {
    data: attempts,
    isLoading,
    refetch,
  } = useQuery(
    trpc.pelatihan.assessment.getAttemptsForGrading.queryOptions({
      pelatihanId,
      status: statusFilter === "all" ? undefined : statusFilter,
    }),
  );

  // Query details of specific attempt
  const { data: attemptDetails, isLoading: isLoadingDetails } = useQuery(
    trpc.pelatihan.assessment.getAttemptDetails.queryOptions(
      { attemptId: activeAttemptId! },
      { enabled: !!activeAttemptId },
    ),
  );

  // Mutation to save grades
  const gradeMutation = useMutation(
    trpc.pelatihan.assessment.gradeEssayAnswers.mutationOptions({
      onSuccess: () => {
        toast.success("Penilaian esai berhasil disimpan");
        setActiveAttemptId(null);
        refetch();
      },
      onError: (err) => {
        toast.error(`Gagal menyimpan penilaian: ${err.message}`);
      },
    }),
  );

  // Load initial essay answers into grading state
  useEffect(() => {
    if (attemptDetails?.answers) {
      const initialGrades: Record<
        string,
        { pointsEarned: number; feedback: string }
      > = {};
      attemptDetails.answers.forEach((ans) => {
        if (ans.questionType === "essay") {
          initialGrades[ans.questionId] = {
            pointsEarned: ans.pointsEarned || 0,
            feedback: ans.feedback || "",
          };
        }
      });
      setEssayGrades(initialGrades);
    }
  }, [attemptDetails]);

  const handlePointsChange = (
    questionId: string,
    value: string,
    maxPoints: number,
  ) => {
    const num = parseFloat(value);
    const validVal = isNaN(num) ? 0 : Math.min(Math.max(0, num), maxPoints);
    setEssayGrades((prev) => ({
      ...prev,
      [questionId]: {
        ...prev[questionId]!,
        pointsEarned: validVal,
      },
    }));
  };

  const handleFeedbackChange = (questionId: string, feedback: string) => {
    setEssayGrades((prev) => ({
      ...prev,
      [questionId]: {
        ...prev[questionId]!,
        feedback,
      },
    }));
  };

  const handleSaveGrades = () => {
    if (!activeAttemptId) return;

    // Check maximum points validation
    for (const [questionId, data] of Object.entries(essayGrades)) {
      const ansDetail = attemptDetails?.answers.find(
        (a) => a.questionId === questionId,
      );
      const maxPoints = ansDetail?.points ?? 10;
      if (data.pointsEarned > maxPoints) {
        toast.error(`Nilai tidak boleh melebihi nilai maksimal (${maxPoints})`);
        return;
      }
    }

    const gradesPayload = Object.entries(essayGrades).map(
      ([questionId, data]) => ({
        questionId,
        pointsEarned: data.pointsEarned,
        isCorrect: data.pointsEarned > 0,
        feedback: data.feedback,
      }),
    );

    gradeMutation.mutate({
      attemptId: activeAttemptId,
      grades: gradesPayload,
    });
  };

  const formatDate = (dateStr: string | null) => {
    if (!dateStr) return "—";
    try {
      const date = new Date(dateStr);
      return date.toLocaleDateString("id-ID", {
        day: "2-digit",
        month: "short",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit",
      });
    } catch {
      return dateStr;
    }
  };

  const listAttempts = attempts || [];

  return (
    <div className="space-y-4">
      {/* Search & Filter */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <span className="text-xs font-semibold text-slate-500">
            Status Penilaian:
          </span>
          <div className="w-48">
            <Select
              value={statusFilter}
              onValueChange={(val) => setStatusFilter(val)}
            >
              <SelectTrigger className="h-9 rounded-lg border-[#E2E8F0] bg-white text-xs">
                <SelectValue placeholder="Pilih Status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Semua Status</SelectItem>
                <SelectItem value="submitted">
                  Perlu Penilaian (Esai)
                </SelectItem>
                <SelectItem value="graded">Selesai Dinilai</SelectItem>
                <SelectItem value="in_progress">Sedang Dikerjakan</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
      </div>

      {/* Data Table */}
      <div className="overflow-hidden rounded-xl border border-[#E2E8F0] bg-white shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[850px] text-left">
            <thead>
              <tr className="border-b border-slate-100 bg-slate-50/50">
                <th className="w-10 px-5 py-4 text-xs font-semibold text-[#768094]">
                  No
                </th>
                <th className="px-5 py-4 text-xs font-semibold text-[#768094]">
                  Nama Peserta
                </th>
                <th className="px-5 py-4 text-xs font-semibold text-[#768094]">
                  Nama Ujian
                </th>
                <th className="px-5 py-4 text-xs font-semibold text-[#768094]">
                  Tipe
                </th>
                <th className="px-5 py-4 text-xs font-semibold text-[#768094]">
                  Status
                </th>
                <th className="px-5 py-4 text-xs font-semibold text-[#768094]">
                  Diserahkan Pada
                </th>
                <th className="w-24 px-5 py-4 text-center text-xs font-semibold text-[#768094]">
                  Skor
                </th>
                <th className="w-32 px-5 py-4 text-center text-xs font-semibold text-[#768094]">
                  Aksi
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {isLoading ? (
                Array.from({ length: 5 }).map((_, idx) => (
                  <tr key={idx}>
                    <td className="px-5 py-4">
                      <Skeleton className="h-4 w-6" />
                    </td>
                    <td className="px-5 py-4">
                      <Skeleton className="mb-1 h-4 w-32" />
                      <Skeleton className="h-3 w-40" />
                    </td>
                    <td className="px-5 py-4">
                      <Skeleton className="h-4 w-28" />
                    </td>
                    <td className="px-5 py-4">
                      <Skeleton className="h-4 w-16" />
                    </td>
                    <td className="px-5 py-4">
                      <Skeleton className="h-6 w-24 rounded-full" />
                    </td>
                    <td className="px-5 py-4">
                      <Skeleton className="h-4 w-24" />
                    </td>
                    <td className="px-5 py-4 text-center">
                      <Skeleton className="mx-auto h-4 w-8" />
                    </td>
                    <td className="px-5 py-4 text-center">
                      <Skeleton className="mx-auto h-8 w-24 rounded-md" />
                    </td>
                  </tr>
                ))
              ) : listAttempts.length === 0 ? (
                <tr>
                  <td
                    colSpan={8}
                    className="px-5 py-12 text-center text-sm font-medium text-slate-400"
                  >
                    Tidak ada data pengerjaan ujian.
                  </td>
                </tr>
              ) : (
                listAttempts.map((row, i) => {
                  const statusInfo = statusAttemptConfig[row.status] || {
                    label: row.status,
                    cls: "bg-slate-100 text-slate-600 border-slate-200",
                  };
                  return (
                    <tr
                      key={row.attemptId}
                      className="transition-colors hover:bg-slate-50/50"
                    >
                      <td className="px-5 py-4 text-xs font-semibold text-[#768094]">
                        {i + 1}
                      </td>
                      <td className="px-5 py-4">
                        <p className="text-xs font-semibold text-[#4D4D4D]">
                          {row.participantName || row.userName || "—"}
                        </p>
                        <p className="mt-0.5 text-[10px] text-[#768094]">
                          {row.userEmail}
                        </p>
                      </td>
                      <td className="px-5 py-4 text-xs font-semibold text-[#4D4D4D]">
                        {row.assessmentTitle}
                      </td>
                      <td className="px-5 py-4 text-xs font-medium text-[#768094] capitalize">
                        {row.assessmentType === "pre_test"
                          ? "Pre-Test"
                          : "Post-Test"}
                      </td>
                      <td className="px-5 py-4">
                        <Badge
                          variant="outline"
                          className={`rounded-full px-2.5 py-0.5 text-[10px] font-semibold ${statusInfo.cls}`}
                        >
                          {statusInfo.label}
                        </Badge>
                      </td>
                      <td className="px-5 py-4 text-xs font-medium text-[#768094]">
                        {formatDate(row.submittedAt)}
                      </td>
                      <td className="px-5 py-4 text-center">
                        {row.score !== null ? (
                          <span
                            className={`text-xs font-bold ${
                              row.score >= 70
                                ? "text-emerald-600"
                                : "text-red-500"
                            }`}
                          >
                            {row.score}%
                          </span>
                        ) : (
                          <span className="flex items-center justify-center gap-1 text-xs font-medium text-amber-600">
                            <IconAlertCircle className="size-3 shrink-0" />
                            Belum Dinilai
                          </span>
                        )}
                      </td>
                      <td className="px-5 py-4 text-center">
                        {row.status === "submitted" ? (
                          <Button
                            size="sm"
                            className="h-8 bg-[#1061D6] text-xs font-semibold text-white hover:bg-blue-700"
                            onClick={() => setActiveAttemptId(row.attemptId)}
                          >
                            <IconClipboardCheck className="mr-1 size-3.5" />
                            Nilai Esai
                          </Button>
                        ) : (
                          <Button
                            size="sm"
                            variant="outline"
                            className="h-8 border-[#E2E8F0] text-xs font-semibold text-[#768094] hover:text-[#4D4D4D]"
                            onClick={() => setActiveAttemptId(row.attemptId)}
                          >
                            Lihat Detail
                          </Button>
                        )}
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Grading Dialog Modal */}
      <Dialog
        open={!!activeAttemptId}
        onOpenChange={(open) => !open && setActiveAttemptId(null)}
      >
        <DialogContent className="max-h-[85vh] max-w-3xl overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Penilaian Jawaban Ujian</DialogTitle>
            <DialogDescription>
              Silakan evaluasi dan berikan nilai pada jawaban esai peserta di
              bawah ini.
            </DialogDescription>
          </DialogHeader>

          {isLoadingDetails || !attemptDetails ? (
            <div className="flex flex-col items-center justify-center space-y-4 py-12">
              <IconLoader2 className="h-8 w-8 animate-spin text-primary" />
              <p className="text-sm font-medium text-slate-500">
                Memuat lembar pengerjaan...
              </p>
            </div>
          ) : (
            <div className="my-4 space-y-6">
              {/* Participant & Exam Header Info */}
              <div className="grid grid-cols-2 gap-4 rounded-xl border border-slate-100 bg-slate-50 p-4 text-xs">
                <div>
                  <p className="font-medium text-[#768094]">Peserta</p>
                  <p className="mt-0.5 font-bold text-[#4D4D4D]">
                    {attemptDetails.attempt.enrollment.participantName ||
                      attemptDetails.attempt.enrollment.user.name}
                  </p>
                  <p className="mt-0.5 text-[#768094]">
                    {attemptDetails.attempt.enrollment.user.email}
                  </p>
                </div>
                <div>
                  <p className="font-medium text-[#768094]">Ujian / Kuis</p>
                  <p className="mt-0.5 font-bold text-[#4D4D4D]">
                    {attemptDetails.attempt.assessment.title}
                  </p>
                  <p className="mt-0.5 text-[#768094] capitalize">
                    {attemptDetails.attempt.assessment.type === "pre_test"
                      ? "Pre-Test"
                      : "Post-Test"}{" "}
                    · Passing Score:{" "}
                    {attemptDetails.attempt.assessment.passingScore}%
                  </p>
                </div>
              </div>

              {/* Answers list */}
              <div className="space-y-6">
                <h3 className="border-b pb-2 text-sm font-bold text-[#4D4D4D]">
                  Lembar Jawaban
                </h3>

                {attemptDetails.answers.map((ans, idx) => {
                  const isEssay = ans.questionType === "essay";

                  return (
                    <div
                      key={ans.questionId}
                      className="space-y-3 rounded-xl border border-slate-100 bg-white p-4 shadow-sm"
                    >
                      <div className="flex items-start justify-between gap-3">
                        <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-slate-100 text-[10px] font-bold text-slate-600">
                          {idx + 1}
                        </span>
                        <p className="flex-1 text-sm leading-relaxed font-bold text-[#4D4D4D]">
                          {ans.questionText}
                        </p>
                        <Badge
                          variant="secondary"
                          className="shrink-0 text-[10px] font-semibold"
                        >
                          Nilai Max: {ans.points || 10}
                        </Badge>
                      </div>

                      {/* Display based on question type */}
                      {isEssay ? (
                        <div className="space-y-4 pt-1">
                          {/* Student answer */}
                          <div className="space-y-1.5">
                            <p className="text-xs font-semibold text-slate-500">
                              Jawaban Peserta:
                            </p>
                            <div className="rounded-lg border border-slate-100 bg-slate-50/70 p-3 text-sm leading-relaxed whitespace-pre-line text-[#4D4D4D] italic">
                              {ans.userAnswer || (
                                <span className="text-slate-400 italic">
                                  Peserta tidak mengisi jawaban.
                                </span>
                              )}
                            </div>
                          </div>

                          {/* Points and Feedback Inputs */}
                          {attemptDetails.attempt.status === "submitted" ? (
                            <div className="grid grid-cols-1 items-start gap-4 border-t pt-3 md:grid-cols-4">
                              <div className="space-y-1.5 md:col-span-1">
                                <Label
                                  htmlFor={`score-${ans.questionId}`}
                                  className="text-xs font-semibold text-slate-600"
                                >
                                  Berikan Nilai (0-{ans.points || 10}):
                                </Label>
                                <Input
                                  id={`score-${ans.questionId}`}
                                  type="number"
                                  min={0}
                                  max={ans.points || 10}
                                  step={0.5}
                                  value={
                                    essayGrades[ans.questionId]?.pointsEarned ??
                                    ""
                                  }
                                  onChange={(e) =>
                                    handlePointsChange(
                                      ans.questionId,
                                      e.target.value,
                                      ans.points || 10,
                                    )
                                  }
                                  className="h-9 text-sm"
                                />
                              </div>
                              <div className="space-y-1.5 md:col-span-3">
                                <Label
                                  htmlFor={`feedback-${ans.questionId}`}
                                  className="text-xs font-semibold text-slate-600"
                                >
                                  Umpan Balik / Feedback (Opsional):
                                </Label>
                                <Textarea
                                  id={`feedback-${ans.questionId}`}
                                  placeholder="Tulis masukan atau koreksi untuk peserta..."
                                  value={
                                    essayGrades[ans.questionId]?.feedback ?? ""
                                  }
                                  onChange={(e) =>
                                    handleFeedbackChange(
                                      ans.questionId,
                                      e.target.value,
                                    )
                                  }
                                  className="h-9 min-h-[60px] py-2 text-sm"
                                />
                              </div>
                            </div>
                          ) : (
                            <div className="grid grid-cols-1 items-start gap-4 rounded-lg border-t bg-slate-50/30 p-2.5 pt-3 text-xs md:grid-cols-4">
                              <div className="md:col-span-1">
                                <p className="font-semibold text-slate-500">
                                  Nilai Diberikan:
                                </p>
                                <p className="mt-0.5 text-sm font-bold text-emerald-600">
                                  {ans.pointsEarned} / {ans.points || 10}
                                </p>
                              </div>
                              <div className="md:col-span-3">
                                <p className="font-semibold text-slate-500">
                                  Umpan Balik:
                                </p>
                                <p className="mt-0.5 leading-relaxed text-slate-600">
                                  {ans.feedback || (
                                    <span className="text-slate-400 italic">
                                      Tidak ada feedback
                                    </span>
                                  )}
                                </p>
                              </div>
                            </div>
                          )}
                        </div>
                      ) : (
                        // Multiple choice representation
                        <div className="space-y-2 pt-1 pl-8">
                          <p className="text-xs font-semibold text-slate-500">
                            Jawaban Peserta:
                          </p>
                          <div className="space-y-1">
                            {ans.options?.map((opt) => {
                              const isSelected = ans.userAnswer === opt.id;
                              const isCorrect = opt.isCorrect;

                              let optionClass =
                                "border-slate-100 text-slate-600";
                              let iconElement = null;

                              if (isSelected) {
                                if (isCorrect) {
                                  optionClass =
                                    "border-emerald-200 bg-emerald-50 text-emerald-800 font-medium";
                                  iconElement = (
                                    <IconCheck className="size-3.5 shrink-0 text-emerald-600" />
                                  );
                                } else {
                                  optionClass =
                                    "border-red-200 bg-red-50 text-red-800 font-medium";
                                  iconElement = (
                                    <IconX className="size-3.5 shrink-0 text-red-600" />
                                  );
                                }
                              } else if (isCorrect) {
                                optionClass =
                                  "border-emerald-200 text-emerald-800 bg-emerald-50/30";
                              }

                              return (
                                <div
                                  key={opt.id}
                                  className={`flex items-center gap-2 rounded-lg border p-2.5 text-xs leading-relaxed ${optionClass}`}
                                >
                                  {iconElement}
                                  <span>{opt.optionText}</span>
                                  {isCorrect && !isSelected && (
                                    <span className="ml-auto text-[10px] font-bold text-emerald-600">
                                      (Kunci Jawaban)
                                    </span>
                                  )}
                                </div>
                              );
                            })}
                          </div>

                          <div className="flex items-center gap-1.5 border-t pt-2 text-xs font-semibold">
                            <span>Hasil Penilaian Auto:</span>
                            {ans.isCorrect ? (
                              <span className="rounded-full border border-emerald-100 bg-emerald-50 px-2 py-0.5 text-[10px] text-emerald-600">
                                Benar (+{ans.pointsEarned} Poin)
                              </span>
                            ) : (
                              <span className="rounded-full border border-red-100 bg-red-50 px-2 py-0.5 text-[10px] text-red-600">
                                Salah (0 Poin)
                              </span>
                            )}
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          <DialogFooter className="border-t pt-4">
            <Button
              variant="outline"
              onClick={() => setActiveAttemptId(null)}
              disabled={gradeMutation.isPending}
            >
              Tutup
            </Button>
            {attemptDetails?.attempt.status === "submitted" && (
              <Button
                onClick={handleSaveGrades}
                disabled={gradeMutation.isPending}
                className="bg-[#1061D6] font-semibold text-white hover:bg-blue-700"
              >
                {gradeMutation.isPending && (
                  <IconLoader2 className="mr-2 h-4 w-4 animate-spin" />
                )}
                Simpan Penilaian
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
